  it('scores a -1 with invalid trace data', () => {
    const artifacts = GatherRunner.instantiateComputedArtifacts();
    artifacts.traces = {
      [Audit.DEFAULT_PASS]: {
        traceEvents: [{pid: 15256, tid: 1295, t: 5}]
      }
